import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.BLL-IG04.js";const u=JSON.parse('{"title":"How-to: gate CI on docs","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/ci-gate.md","filePath":"how-to/ci-gate.md"}'),n={name:"how-to/ci-gate.md"};function o(h,e,r,l,c,d){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="how-to-gate-ci-on-docs" tabindex="-1">How-to: gate CI on docs <a class="header-anchor" href="#how-to-gate-ci-on-docs" aria-label="Permalink to &quot;How-to: gate CI on docs&quot;">​</a></h1><p><code>mimus check</code> is the mechanical tier — deterministic, offline, safe to gate. Exit <code>1</code> when any <code>error</code>-severity violation exists.</p><h2 id="the-gate" tabindex="-1">The gate <a class="header-anchor" href="#the-gate" aria-label="Permalink to &quot;The gate&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Wire it like a test: run in CI on every PR. Doc paths, commands, symbols and your <code>rules/*.toml</code> conventions all gate the same way.</p><h2 id="no-cmd-—-never-execute-anything" tabindex="-1"><code>--no-cmd</code> — never execute anything <a class="header-anchor" href="#no-cmd-—-never-execute-anything" aria-label="Permalink to &quot;`--no-cmd` — never execute anything&quot;">​</a></h2><p>The <code>cmd</code> checker verifies documented commands exist on PATH — it does <strong>not</strong> run them. But if you want to be explicit that a job runs nothing executable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-cmd</span></span></code></pre></div><p><code>--no-cmd</code> skips the command checker entirely; path/symbol/rules checks still run.</p><h2 id="severity-is-the-gate-boundary" tabindex="-1">Severity is the gate boundary <a class="header-anchor" href="#severity-is-the-gate-boundary" aria-label="Permalink to &quot;Severity is the gate boundary&quot;">​</a></h2><ul><li><code>error</code> — mechanical, reproducible: dead paths, missing binaries, rule violations marked <code>severity = &quot;error&quot;</code>.</li><li><code>warn</code> — env-dependent or heuristic: shown in output and <code>--format json</code>, never fails the run.</li></ul><p>Tune per rule in <code>rules/*.toml</code> (<code>severity = &quot;warn&quot;</code>).</p><h2 id="report-for-humans" tabindex="-1">Report for humans <a class="header-anchor" href="#report-for-humans" aria-label="Permalink to &quot;Report for humans&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # always exits 0 — full list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # machine-readable for tooling</span></span></code></pre></div><p><code>report</code> is the audit-view command: same violations, never a gate. <code>reconcile</code>-style tooling consumes the JSON.</p><h2 id="recommended-setup" tabindex="-1">Recommended setup <a class="header-anchor" href="#recommended-setup" aria-label="Permalink to &quot;Recommended setup&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># whatever your CI is</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mimus check --no-cmd</span></span></code></pre></div><p>Docs that can drift silently are docs that will. One line keeps them honest.</p><p>See <a href="./../explanation/claims.html">claims &amp; tiers</a> for why the semantic tier can never be this gate.</p>',19)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
